#include <r_io.h>
#include <sdb/sdb.h>
#include <config.h>

R_LIB_VERSION (r_io);

R_API RIO* r_io_new(void) {
        RIO *io = R_NEW0 (RIO);
        r_io_init (io);
        return io;
}

R_API void r_io_init(RIO* io) {
        r_return_if_fail (io);
        io->addrbytes = 1;
        io->overlay = true;
        io->cb_printf = printf;
        r_io_desc_init (io);
        r_io_bank_init (io);
        r_io_map_init (io);
        r_io_cache_init (io);
        r_io_plugin_init (io);
        r_io_undo_init (io);
        io->event = r_event_new (io);
        RIOBank *bank = r_io_bank_new ("default");
        if (bank) {
                io->bank = bank->id;
                r_io_bank_add (io, bank);
        }
}

R_API void r_io_free(RIO *io) {
        if (io) {
                r_io_fini (io);
                free (io);
        }
}

R_API RIODesc *r_io_open_buffer(RIO *io, RBuffer *b, int perm, int mode) {
        r_return_val_if_fail (io && b, NULL);
#if 0
